param([Parameter(Mandatory)][ValidatePattern('^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$')][string]$LeaseId,[Parameter(Mandatory)][ValidatePattern('^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$')][string]$DeploymentId,[Parameter(Mandatory)][ValidateLength(1,128)][string]$Provider,
    [Parameter(Mandatory)][ValidateRange(1,2147483647)][int]$Generation,[Parameter(Mandatory)][ValidateRange(1,1440)][int]$ValidityMinutes,
    [Parameter(Mandatory)][string]$SecretRoot,[Parameter(Mandatory)][string[]]$SecretFiles,[Parameter(Mandatory)][string]$SigningPrivateKeyFile,
    [Parameter(Mandatory)][ValidatePattern('^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$')][string]$SigningKeyId,[Parameter(Mandatory)][string]$ReleaseSigningPublicKeyFile,[Parameter(Mandatory)][string]$OutputDirectory)
$ErrorActionPreference='Stop';. "$PSScriptRoot/BackupRestore.Common.ps1";$root=Assert-BackupPathOutsideRepository $SecretRoot 'SecretRoot';$output=[IO.Path]::GetFullPath($OutputDirectory);$prefix=$root.TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar;if(-not($output+[IO.Path]::DirectorySeparatorChar).StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw 'Secret lease output must be beneath SecretRoot'};New-Item -ItemType Directory $output -Force|Out-Null;$seen=@{};$entries=@();foreach($secret in $SecretFiles){$file=[IO.Path]::GetFullPath($secret);if(-not($file+[IO.Path]::DirectorySeparatorChar).StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)-or-not(Test-Path $file -PathType Leaf)){throw 'Leased Secret must be an existing file beneath SecretRoot'};if($seen.ContainsKey($file)){throw 'Secret lease contains a duplicate path'};$seen[$file]=$true;$item=Get-Item $file -Force;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0-or$item.Length-le0-or$item.Length-gt1MB){throw 'Secret lease file must be a regular file between 1 byte and 1 MiB'};$entries+=[ordered]@{RelativePath=[IO.Path]::GetRelativePath($root,$file);Size=$item.Length;Sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$signer=Get-BackupKeyFingerprint $SigningPrivateKeyFile 'Secret lease' $true;$release=Get-BackupKeyFingerprint $ReleaseSigningPublicKeyFile 'Release signer' $false;if($signer-ceq$release){throw 'Secret lease signer and release signer must be separated'};$issued=[DateTimeOffset]::UtcNow;$lease=[ordered]@{SchemaVersion=1;Product='ET.Server';ArtifactType='SecretLease';LeaseId=$LeaseId;DeploymentId=$DeploymentId;Provider=$Provider;Generation=$Generation;IssuedAtUtc=$issued.ToString('O');ExpiresAtUtc=$issued.AddMinutes($ValidityMinutes).ToString('O');SigningKeyId=$SigningKeyId;SigningPublicKeySha256=$signer;ReleaseSigningPublicKeySha256=$release;Secrets=$entries};$file=Join-Path $output "$LeaseId.secret-lease.json";if((Test-Path $file)-or(Test-Path "$file.sig")){throw 'Secret lease already exists'};$bytes=$script:BackupRestoreUtf8.GetBytes(($lease|ConvertTo-Json -Depth 8));try{[IO.File]::WriteAllBytes($file,$bytes);[IO.File]::WriteAllBytes("$file.sig",(New-BackupSignature $bytes $SigningPrivateKeyFile 'Secret lease'));[ordered]@{Passed=$true;LeaseFile=$file;SignatureFile="$file.sig";LeaseId=$LeaseId;Generation=$Generation;ExpiresAtUtc=$lease.ExpiresAtUtc;Secrets=$entries.Count;LeaseSha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}|ConvertTo-Json}catch{foreach($path in @($file,"$file.sig")){if(Test-Path $path){Remove-Item $path -Force}};throw}
